style.css:
@-moz-document domain("qbo.intuit.com") {
/* Modificación de customerMessage */
    .universal .messagesAndAmounts .customerMessage {
        height: 200px !important;
        width: 1000px !important;
        resize: none !important;
    }

    /* Modificación de memoText */
    .universal .messagesAndAmounts .memoText {
        width: 1000px !important;
        height: 100px !important;
        resize: none !important;
    }

    /* Modificación de trowser header */
    .trowser .header {
        height: 50px !important;
        background-color: #08267e !important;
        color: white !important;
        position: relative !important;
        z-index: 3 !important;
        zoom: reset !important;
    }

    /* Modificación de stickyFooter */
    .universal .stickyFooter {
        padding: 8px 15px !important;
        background-color: #08267e !important;
    }
}
